import test, { before, after, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';
import { extractMcpAppCard } from '../scripts/extract-mcp-app-card.mjs';

// R4g-mcp MA-6: the 2.42304.0 transcript MCP App / Visualize widget card (c96d752d0 VX = memo(kQe), PQe), generated by
// scripts/extract-mcp-app-card.mjs over the MA-5 host library. The tests render the generated originals on the server
// with controlled tools, servers and callbacks; the lazy AppRenderer is replaced by a probe that records the props PQe
// passes it. No frame, network, process or real configuration is touched.
const ROOT = path.resolve(import.meta.dirname, '..');
const GEN = path.join(ROOT, 'src/generated/mcp-app-card');
const REF = path.join(ROOT, '../reference/installed-2.42304.0-20261017/ion-dist/assets/v1');
const VISUALIZE_UUID = '6f616b42-0ed8-571e-823f-ee4aca6b7ce9';
const HASH = 'a'.repeat(32);
let server, Card, Adapters, HostStyles;
before(async () => {
  server = await createServer({ configFile: false, root: ROOT, plugins: [react()],
    server: { middlewareMode: true, hmr: false, ws: false, watch: null }, appType: 'custom', logLevel: 'error' });
  Card = await server.ssrLoadModule('/src/generated/mcp-app-card/tool-card.mjs');
  Adapters = await server.ssrLoadModule('/src/source-mcp-app-card-adapters.jsx');
  HostStyles = await server.ssrLoadModule('/src/generated/mcp-app-host/host-styles.mjs');
});
after(() => server?.close());
beforeEach(() => Adapters.mcpAppCardHost.reset());

const h = React.createElement;
const visualizeServer = () => ({ uuid: VISUALIZE_UUID, name: 'visualize', type: 'local', isBuiltIn: true,
  tools: [{ name: 'show_widget', _meta: { ui: { resourceUri: 'ui://imagine/show-widget.html' } } }, { name: 'read_me' }] });
const thirdPartyServer = (extra = {}) => ({ uuid: 'srv-1', name: 'weather', type: 'local', sessionOwned: true,
  tools: [{ name: 'forecast', _meta: { ui: { resourceUri: 'ui://weather/forecast.html' } } }, { name: 'plain' }], ...extra });
const visualizeMatch = () => Adapters.matchSessionMcpTool('mcp__visualize__show_widget', { servers: [visualizeServer()] });
const weatherMatch = () => Adapters.matchSessionMcpTool('mcp__weather__forecast', { servers: [thirdPartyServer()] });

// PQe with the props kQe computes once the hash is known; the AppRenderer chunk is a probe recording its props.
function renderWidget(props = {}) {
  const seen = [];
  const handle = Card.appRendererChunk.handle;
  const saved = { module: handle.module, resident: handle.resident, ssr: handle.ssr };
  assert.equal(handle.ssr, false, 'DX is ssr:false');
  // The probe stands in for the resident AppRenderer (test only: the server render draws it).
  handle.module = function Probe(p) { seen.push(p); return h('div', { 'data-probe': '' }); };
  handle.resident = true;
  handle.ssr = true;
  try {
    const match = props.match ?? visualizeMatch();
    const html = renderToStaticMarkup(h(Card.McpAppWidgetCard, {
      tool: { id: 'call-1', name: 'mcp__visualize__show_widget', status: 'completed', input: { title: 'Chart' }, rawResultContent: [{ type: 'text', text: 'ok' }] },
      sessionRef: { type: 'local', id: 's1' }, sharesWithSession: true, match, serverUuid: match?.server.uuid, serverIdentifier: match?.server.uuid,
      sessionOwned: false, firstPartyServer: true, client: { getServerCapabilities: () => ({ resources: {} }) },
      sandboxProxyUrl: new URL(Adapters.MCP_APP_SANDBOX_PROXY_URL), conversationHash: HASH, expanded: true, onToggleExpanded() {}, onInitError() {},
      onInitialized() {}, hostResident: false, reservedHeight: 0, ...props }));
    return { html, props: seen.at(-1) };
  } finally { Object.assign(handle, saved); }
}

test('generated output is current (--check), pins its sources and names its host boundaries', async () => {
  const manifest = await extractMcpAppCard({ check: true });
  assert.equal(manifest.referenceVersion, '2.42304.0');
  const bySource = Object.fromEntries(manifest.modules.map(m => [m.source, m]));
  for (const [file, target] of [['c96d752d0-BOCqU7c2.js', 'tool-card.mjs'], ['c52b02f3f-DUwt0Dsx.js', 'visual-messages.mjs'],
    ['shared-156-Bikz018e.js', 'tool-names.mjs'], ['cfdfec14c-3LbBfVtj.js', 'cfdfec14c.mjs'], ['c8e12f1a8-6AP_7dPS.js', 'c8e12f1a8.mjs']]) {
    assert.equal(bySource[file]?.target, target, file);
    const bytes = await fs.readFile(path.join(REF, file));
    assert.equal(bySource[file].sourceSha256, createHash('sha256').update(bytes).digest('hex'), file);
  }
  // The card's only dynamic import is the AppRenderer chunk, re-pointed at the MA-5 library (one AppRenderer for both).
  assert.deepEqual(bySource['c96d752d0-BOCqU7c2.js'].dynamicImports, [{ binding: 'DX', rewrites: { 'cd9b7fccf-C8-F2T2b.js': '../mcp-app-host/app-renderer.mjs' } }]);
  for (const name of await fs.readdir(GEN)) if (name.endsWith('.mjs'))
    assert.doesNotMatch(await fs.readFile(path.join(GEN, name), 'utf8'), /from "\.\.\/mcp-app-host\/(app-renderer|app-bridge|zod|mcp-protocol)\.mjs"/, `${name} must not import the renderer statically`);
  // Shared with MA-5: the gate, the hash, the host context, the style table, the activation check.
  const hostImports = manifest.modules.flatMap(m => m.imports.filter(i => i.kind === 'mcp-app-host').map(i => `${i.via}=${i.from.split('/').pop()}:${i.name}`));
  for (const expected of ['cbc7fd025-CAGIpAIM.js:c=sandbox-origin.mjs:c', 'c8e12f1a8-6AP_7dPS.js:n=host-context.mjs:useMcpAppHostContext',
    'c8e12f1a8-6AP_7dPS.js:t=host-context.mjs:useKeepMenuClear', 'c06a5ffab-BHsFLtx8.js:t=widget-size.mjs:t', 'cbc4150d0-BRaVNt32.js:n=host-styles.mjs:MCP_APP_STYLE_VARIABLES',
    'c89766c40-D_7i6Bva.js:n=user-activation.mjs:n', 'shared-78-D6VXYXaQ.js:X_=sandbox-frame.mjs:toolUiResourceUri'])
    assert.ok(hostImports.includes(expected), expected);
  // Every adapter answers a named original (chunk:alias or a cut local), each once.
  const adapterNames = new Set(manifest.modules.flatMap(m => m.imports.filter(i => i.kind === 'adapter').map(i => i.name)));
  const exported = new Set(Object.keys(Adapters));
  for (const name of adapterNames) assert.ok(exported.has(name), `adapter ${name} is exported`);
  assert.deepEqual(Object.keys(bySource['c96d752d0-BOCqU7c2.js'].localCuts).sort(), ['BZe', 'Uz', 'zZe']);
  assert.deepEqual(manifest.callSites.map(s => s.binding), ['KBe', 'm2e', 'e0', 'UQe']);
});

