test('YZe: every reason the widget does not render, in the official order', () => {
  const ok = { gateOn: true, serverUuid: 'u', headerlessUnverified: false, connectorRowsFromElsewhere: false, serverType: 'local', hasClient: true,
    hasSandboxProxyUrl: true, conversationHashPending: false, hasInitError: false, hostChunk: 'pending', hostChunkRetried: false, isPendingApproval: false,
    resultPayloadMissing: false, callNotRun: false };
  const reason = Card.mcpAppSkipReason;
  assert.equal(reason(ok), null);
  for (const [patch, expected] of [
    [{ gateOn: false }, 'gate_off'], [{ serverUuid: undefined }, 'server_unknown'], [{ headerlessUnverified: true }, 'unverified'],
    [{ connectorRowsFromElsewhere: true }, 'connector_rows_from_elsewhere'], [{ hasClient: false }, 'local_client_missing'],
    [{ hasClient: false, serverType: 'remote' }, 'remote_client_missing'], [{ hasSandboxProxyUrl: false }, 'sandbox_url_missing'],
    [{ conversationHashPending: true }, 'conversation_hash_pending'], [{ hasInitError: true }, 'init_error'], [{ hostChunk: 'failed' }, 'host_chunk_failed'],
    [{ hostChunkRetried: true }, 'host_chunk_not_resident'], [{ hostChunkRetried: true, hostChunk: 'resident' }, null], [{ isPendingApproval: true }, 'pending_approval'],
    [{ resultPayloadMissing: true }, 'result_payload_missing'], [{ callNotRun: true }, 'call_not_run'],
    // Earlier checks win.
    [{ gateOn: false, serverUuid: undefined }, 'gate_off'], [{ hasClient: false, hasSandboxProxyUrl: false }, 'local_client_missing'],
  ]) assert.equal(reason({ ...ok, ...patch }), expected, JSON.stringify(patch));
  assert.equal(Card.SKIP_REASON_OUTCOME.host_chunk_not_resident, 'host_chunk_failed');
  assert.equal(Card.SKIP_REASON_OUTCOME.call_not_run, 'result_payload_missing');
});

test('pure helpers: tool name prefixes, visualize status, middle truncation, composer text', () => {
  const strip = Card.stripToolServerPrefix;
  assert.equal(strip('mcp__weather__forecast', 'weather'), 'forecast');
  assert.equal(strip('weather:forecast', 'weather'), 'forecast');
  assert.equal(strip('mcp__other__tool__x'), 'tool__x');
  assert.equal(strip('mcp__remote-devices__laptop__open'), 'open');
  assert.equal(strip('plain'), 'plain');
  assert.equal(Card.visualizeStatus({ status: 'running' }, true), 'making');
  assert.equal(Card.visualizeStatus({ status: 'completed' }, false), 'made');
  assert.equal(Card.visualizeStatus({ status: 'completed', isError: true }, false), 'failed');
  assert.equal(Card.visualizeStatus({ status: 'completed', interrupted: true, isError: true }, false), 'settled');
  assert.equal(Card.truncateMiddle('abcdefghijklmnopqrstuvwxyz', 10), 'abcde…wxyz');
  assert.equal(Card.truncateMiddle('short', 10), 'short');
  assert.equal(Card.messageTextForComposer([{ type: 'text', text: 'Make the bars blue' }, { type: 'image', data: '' }]), 'Make the bars blue');
  assert.equal(Card.messageTextForComposer([{ type: 'text', text: '/compact' }]), null, 'a slash command is not prefilled');
  assert.equal(Card.messageTextForComposer([{ type: 'text', text: '   ' }]), null);
  assert.equal(Card.isVisualizeMatch(visualizeMatch(), 'mcp__visualize__show_widget'), true);
  assert.equal(Card.isVisualizeMatch(weatherMatch(), 'mcp__weather__forecast'), false);
});

test('visualize card: Making / Made / Failed to make a visual', () => {
  const running = renderWidget({ tool: { id: 'v1', name: 'mcp__visualize__show_widget', status: 'running', input: {} } }).html;
  assert.match(running, /data-shimmering="true"[^>]*>Making a visual</);
  assert.match(running, /data-mcp-app-card=""/);
  // Until the widget reports ui/notifications/initialized an open card still says Making (wn = ft || (Ee && !we)).
  assert.match(renderWidget().html, /data-shimmering="true"[^>]*>Making a visual</);
  const done = renderWidget({ expanded: false }).html;
  assert.match(done, />Made a visual</);
  assert.doesNotMatch(done, /data-shimmering="true"/);
  const failed = renderWidget({ expanded: false, tool: { id: 'v2', name: 'mcp__visualize__show_widget', status: 'completed', isError: true, input: {}, rawResultContent: [] } }).html;
  assert.match(failed, /text-danger[^>]*>Failed to make a visual</);
  // Visualize cards are padded and have no server header (nQe off), only the disclosure row.
  assert.match(running, /class="relative rounded-lg overflow-hidden border border-alpha-2 p-md"/);
  assert.doesNotMatch(done, /data-mcp-app-card/, 'a collapsed card keeps its body unmounted until first opened (c425fb3cf F)');
  assert.doesNotMatch(running, /Showing in another pane|Show here|Show more/);
});

test('third-party card: Widget from {server}, Rendering widget, and the SSH host form (toolcards-11, unreachable at run time)', () => {
  const tool = { id: 'w1', name: 'mcp__weather__forecast', status: 'completed', input: { city: 'Oslo' }, rawResultContent: [{ type: 'text', text: 'sunny' }] };
  const base = { tool, match: weatherMatch(), firstPartyServer: false, sessionOwned: true, expanded: false };
  const done = renderWidget(base);
  assert.match(done.html, />Widget from weather</);
  assert.match(done.html, /text-code truncate min-w-0 text-primary">forecast</);
  assert.doesNotMatch(done.html, / p-md/);
  assert.match(renderWidget({ ...base, tool: { ...tool, status: 'running' } }).html, />Rendering widget</);
  const ssh = renderWidget({ ...base, sshHostLabel: 'build-box' }).html;
  assert.match(ssh, />Widget from a server on build-box: weather</);
  assert.match(ssh, /class="sr-only">A server on build-box: weather\. forecast</);
});

