test('ui/message prefills the composer only with an iframe-originated activation; ui/open-link refuses non-https and rejected links', async () => {
  const prefilled = [];
  const { props } = renderWidget({ onPrefillComposer: text => { prefilled.push(text); } });
  const warn = console.warn;
  console.warn = () => {};
  const nav = Object.getOwnPropertyDescriptor(globalThis, 'navigator');
  const now = performance.now;
  try {
    const message = { role: 'user', content: [{ type: 'text', text: 'Make the bars blue' }] };
    assert.deepEqual(await props.onmessage(message), { isError: true }, 'no user activation');
    assert.deepEqual(prefilled, []);
    Object.defineProperty(globalThis, 'navigator', { configurable: true, value: { userActivation: { isActive: true }, userAgent: 'test' } });
    performance.now = () => now.call(performance) + 60_000;
    assert.deepEqual(await props.onmessage(message), {});
    assert.deepEqual(prefilled, ['Make the bars blue']);
    assert.deepEqual(await props.onopenlink({ url: 'http://example.com/' }, { mcpReq: { id: 1 } }), { isError: true });
    assert.deepEqual(await props.onopenlink({ url: 'javascript:alert(1)' }, { mcpReq: { id: 2 } }), { isError: true });
  } finally {
    performance.now = now;
    if (nav) Object.defineProperty(globalThis, 'navigator', nav);
    console.warn = warn;
  }
});

test('kQe falls back to the host row until the widget can render', () => {
  const fallback = h('i', null, 'plain row');
  const sessionRef = { type: 'local', id: 's1' };
  const render = (tool, extra = {}) => renderToStaticMarkup(h(Card.McpAppToolCard, { tool, sessionRef, fallback, ...extra }));
  // No server has the tool: server_unknown.
  assert.equal(render({ id: 'k1', name: 'mcp__visualize__show_widget', status: 'completed', input: {} }), '<i>plain row</i>');
  Adapters.mcpAppCardHost.setSessionServers('s1', [visualizeServer(), thirdPartyServer()]);
  Adapters.mcpAppCardHost.setClientFactory(() => ({ getServerCapabilities: () => ({ resources: {} }) }));
  // A tool without a ui:// resource is not an MCP App tool.
  assert.equal(render({ id: 'k2', name: 'mcp__weather__plain', status: 'completed', input: {} }), '<i>plain row</i>');
  // A matched widget waits for the conversation hash (computed after mount; SSR shows the row).
  assert.equal(render({ id: 'k3', name: 'mcp__visualize__show_widget', status: 'completed', input: {}, rawResultContent: [] }), '<i>plain row</i>');
  // Without a fallback the cut Uz asks the host's row renderer.
  const viaContext = renderToStaticMarkup(h(Adapters.McpAppToolRowFallback.Provider, { value: tool => h('b', null, tool.id) },
    h(Card.McpAppToolCard, { tool: { id: 'k4', name: 'mcp__weather__plain', status: 'completed', input: {} }, sessionRef })));
  assert.equal(viaContext, '<b>k4</b>');
});

test('adapters: matching, session ownership, the bridge client, approvals, row memory, the lazy chunk', async () => {
  const state = { servers: [visualizeServer(), thirdPartyServer()] };
  assert.equal(Adapters.matchSessionMcpTool('mcp__weather__forecast', state).tool.name, 'forecast');
  assert.equal(Adapters.matchSessionMcpTool('mcp__unknown__x', state), undefined);
  assert.deepEqual(Adapters.findMcpAppToolServer('mcp__weather__forecast', state), { toolName: 'mcp__weather__forecast', serverUuid: 'srv-1' });
  assert.equal(Adapters.findMcpAppToolServer('mcp__weather__plain', state), undefined);
  assert.equal(Adapters.findMcpAppToolServer('mcp__visualize__read_me', state), undefined);
  assert.equal(Adapters.isSessionOwnedServer(state, 'srv-1'), true);
  assert.equal(Adapters.isSessionOwnedServer(state, VISUALIZE_UUID), false);
  // The bridge client sends the widget's MCP requests to the main process (MA-4 actions).
  const calls = [];
  const savedWindow = globalThis.window;
  globalThis.window = { desktop: { call: async (action, payload) => { calls.push([action, payload]); return { contents: [] }; } } };
  try {
    const client = Adapters.createBridgeMcpAppClient({ sessionId: 's1', server: thirdPartyServer() });
    assert.deepEqual(client.getServerCapabilities(), { resources: {} });
    await client.readResource({ uri: 'ui://weather/forecast.html' });
    await client.request({ method: 'tools/call', params: { name: 'forecast', arguments: { city: 'Oslo' } } });
    await client.request({ method: 'resources/list', params: {} });
    await assert.rejects(client.request({ method: 'prompts/get', params: {} }), /Method not found: prompts\/get/);
    assert.deepEqual(calls.map(([action]) => action), ['mcp-app:read-resource', 'mcp-app:call-tool', 'mcp-app:list-resources']);
    assert.deepEqual(calls[0][1], { sessionId: 's1', server: 'weather', serverUuid: 'srv-1', uri: 'ui://weather/forecast.html' });
    assert.deepEqual(calls[1][1], { sessionId: 's1', server: 'weather', serverUuid: 'srv-1', name: 'forecast', arguments: { city: 'Oslo' }, _meta: undefined });
  } finally { globalThis.window = savedWindow; }
  assert.equal(Adapters.createBridgeMcpAppClient({ sessionId: 's1', server: thirdPartyServer() }), null, 'no desktop bridge, no client');
  // Approvals, row memory.
  Adapters.mcpAppCardHost.setToolApprovals({ s1: { r1: { status: 'pending', toolName: 'mcp__weather__forecast' } } });
  assert.equal(Adapters.toolApprovalStore.getState().requestsBySession.s1.r1.status, 'pending');
  function Row() { const [open] = Adapters.useTranscriptRowExpanded('mcpApp:x'); return String(open); }
  assert.equal(renderToStaticMarkup(h(Row)), 'undefined');
  // The lazy chunk: resident after a successful load, failed (and retried by warm) after a failed one.
  let attempts = 0;
  const chunk = Adapters.defineLazyChunk({ entry: { id: 't', load: async () => { attempts += 1; if (attempts === 1) throw Error('offline'); return { X: () => 'x' }; } }, pick: m => m.X });
  chunk.handle.preload('open');
  await new Promise(resolve => setTimeout(resolve, 0));
  assert.equal(chunk.handle.state, 'failed');
  chunk.handle.warm('open');
  await new Promise(resolve => setTimeout(resolve, 0));
  assert.equal(chunk.handle.resident, true);
  assert.equal(renderToStaticMarkup(h(chunk.Component)), 'x');
});

