test('unreachable host branches throw instead of drawing invented UI', () => {
  assert.throws(() => renderToStaticMarkup(h(Adapters.GatedServerHeaderRow)), /__gb__3106245306/);
  // turnStatusRows (served on): the step-list form is the working line's generated CDS TurnStatus, no longer unreachable.
  assert.equal(typeof Adapters.StepList.Step, 'object');
  assert.throws(() => new Adapters.RemoteMcpClient(), /no remote MCP clients/);
  assert.throws(() => Adapters.isConnectorToolOfServer(), /remote MCP servers only/);
  assert.equal(Adapters.useMcpAppsEnabled(), true);
  assert.equal(Adapters.useMcpAppPaneSupported(), false);
  assert.deepEqual(Adapters.cleanSendText('as written​'), { text: 'as written​', removedCount: 0 });
});
